arguments.file_text:
namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }
    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new()
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious traditional Italian pizza.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                    "Stretch dough into a 12-inch round on a floured surface.",
                    "Spread crushed tomatoes evenly over the dough.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10–12 minutes until crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and a drizzle of olive oil."
                ],
                TotalRatings = 12, RatingSum = 52
            },
            new()
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente.",
                    "Crisp pancetta in a skillet over medium heat.",
                    "Whisk eggs with grated Pecorino and plenty of black pepper.",
                    "Toss hot pasta with pancetta, then quickly stir in egg mixture off heat.",
                    "Serve immediately with extra cheese and pepper."
                ],
                TotalRatings = 8, RatingSum = 36
            },
            new()
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cilantro"],
                Steps = [
                    "Marinate chicken in yogurt and spices for at least 1 hour.",
                    "Grill or broil chicken until charred and cooked through.",
                    "Sauté onion, garlic, and ginger until softened.",
                    "Add tomato sauce and spices; simmer for 15 minutes.",
                    "Stir in cream, add chicken pieces, and simmer 10 more minutes.",
                    "Garnish with cilantro and serve with basmati rice or naan."
                ],
                TotalRatings = 15, RatingSum = 68
            },
            new()
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
                Description = "A vibrant stir-fried noodle dish packed with vegetables.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Carrots", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Lime"],
                Steps = [
                    "Soak rice noodles in warm water for 20 minutes; drain.",
                    "Press and cube tofu, then pan-fry until golden.",
                    "Make sauce by mixing tamarind paste, fish sauce, sugar, and lime juice.",
                    "Stir-fry vegetables over high heat for 2 minutes.",
                    "Add noodles and sauce; toss until noodles are tender.",
                    "Top with crushed peanuts, bean sprouts, and lime wedges."
                ],
                TotalRatings = 6, RatingSum = 25
            },
            new()
            {
                Id = 5, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and zesty avocado dip — perfect as a starter.",
                Ingredients = ["Avocados", "Lime juice", "Red onion", "Jalapeño", "Cilantro", "Tomato", "Salt"],
                Steps = [
                    "Halve and pit avocados; scoop flesh into a bowl.",
                    "Mash with a fork to desired consistency.",
                    "Stir in diced onion, jalapeño, tomato, and cilantro.",
                    "Add lime juice and salt to taste.",
                    "Serve immediately with tortilla chips."
                ],
                TotalRatings = 10, RatingSum = 42
            },
            new()
            {
                Id = 6, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef tacos with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = [
                    "Brown ground beef in a skillet over medium-high heat.",
                    "Add taco seasoning and water; simmer until thickened.",
                    "Warm tortillas in a dry skillet or microwave.",
                    "Fill tortillas with seasoned beef.",
                    "Top with lettuce, tomato, cheese, sour cream, and salsa."
                ],
                TotalRatings = 9, RatingSum = 38
            },
            new()
            {
                Id = 7, Title = "Miso Ramen", Category = "Japanese",
                Description = "A warming bowl of miso-based ramen with rich toppings.",
                Ingredients = ["Ramen noodles", "Miso paste", "Chicken broth", "Soy sauce", "Soft-boiled egg", "Chashu pork", "Green onions", "Nori", "Corn"],
                Steps = [
                    "Bring chicken broth to a simmer; whisk in miso paste and soy sauce.",
                    "Cook ramen noodles according to package directions; drain.",
                    "Prepare soft-boiled eggs (6.5 minutes in boiling water, then ice bath).",
                    "Slice chashu pork and warm briefly in the broth.",
                    "Place noodles in bowls, ladle broth over them.",
                    "Top with halved egg, pork, corn, nori, and sliced green onions."
                ],
                TotalRatings = 11, RatingSum = 49
            },
            new()
            {
                Id = 8, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Individual cakes with a molten chocolate center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = [
                    "Preheat oven to 425°F (220°C). Grease ramekins and dust with cocoa.",
                    "Melt chocolate and butter together; let cool slightly.",
                    "Whisk eggs and sugar until thick and pale.",
                    "Fold chocolate mixture into eggs; gently fold in flour.",
                    "Divide batter among ramekins.",
                    "Bake 12–14 minutes until edges are set but center is soft.",
                    "Invert onto plates and serve immediately."
                ],
                TotalRatings = 14, RatingSum = 65
            },
        ];
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title.Trim(),
            Category = submission.Category.Trim(),
            Description = $"A community-submitted {submission.Category.Trim().ToLowerInvariant()} recipe.",
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

