@page "/recipe/{Id:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe Not Found")</PageTitle>

@if (Recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <h1>@Recipe.Title</h1>
    <p class="recipe-category"><a href="/category/@Recipe.Category">@Recipe.Category</a></p>
    <p class="recipe-description">@Recipe.Description</p>

    <section class="recipe-section">
        <h2>Ingredients</h2>
        <ul>
            @foreach (var ingredient in Recipe.Ingredients)
            {
                <li>@ingredient</li>
            }
        </ul>
    </section>

    <section class="recipe-section">
        <h2>Steps</h2>
        <ol>
            @foreach (var step in Recipe.Steps)
            {
                <li>@step</li>
            }
        </ol>
    </section>

    <section class="recipe-section">
        <h2>Rating</h2>
        <p class="avg-rating">
            Average: @Recipe.AverageRating.ToString("0.0") / 5
            <span class="rating-count">(@Recipe.TotalRatings ratings)</span>
        </p>
        <StarRating RecipeId="@Recipe.Id" />
    </section>

    <p class="back-link"><a href="/category/@Recipe.Category">← Back to @Recipe.Category</a></p>
}

@code {
    [Parameter]
