toolArgs.file_text:
@rendermode InteractiveServer
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="star-rating">
    @if (_submitted)
    {
        <p class="rating-thanks">Thanks! You rated this @_selectedStars star@(_selectedStars != 1 ? "s" : "").</p>
    }
    else
    {
        <span class="star-label">Rate this recipe:</span>
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="star-btn @(star <= _hoveredStar ? "highlighted" : "")"
                    @onmouseover="() => _hoveredStar = star"
                    @onmouseout="() => _hoveredStar = 0"
                    @onclick="() => SubmitRating(star)"
                    aria-label="Rate @star stars">
                @(star <= _hoveredStar ? "★" : "☆")
            </button>
        }
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int _hoveredStar;
    private int _selectedStars;
    private bool _submitted;

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        _selectedStars = stars;
        _submitted = true;
    }
}

