toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (!string.IsNullOrEmpty(_successMessage))
{
    <div class="success-banner">
        <p>@_successMessage</p>
    </div>
}

<EditForm Model="_submission" OnValidSubmit="HandleSubmit" FormName="recipe-submit">
    <div class="form-group">
        <label for="title">Recipe Title</label>
        <InputText id="title" @bind-Value="_submission.Title" placeholder="e.g. Grandma's Apple Pie" />
    </div>

    <div class="form-group">
        <label for="category">Category</label>
        <InputSelect id="category" @bind-Value="_submission.Category">
            <option value="">— Select a category —</option>
            @foreach (var cat in RecipeService.GetCategories())
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
    </div>

    <div class="form-group">
        <label for="ingredients">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" @bind-Value="_submission.Ingredients" rows="6"
            placeholder="2 cups flour&#10;1 cup sugar&#10;3 large apples..." />
    </div>

    <div class="form-group">
        <label for="steps">Steps (one per line)</label>
        <InputTextArea id="steps" @bind-Value="_submission.Steps" rows="6"
            placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients together.&#10;..." />
    </div>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <p class="error-message">@_errorMessage</p>
    }

    <button type="submit" class="submit-btn">Submit Recipe</button>
</EditForm>

@code {
    private RecipeSubmission _submission = new();
    private string? _errorMessage;
    private string? _successMessage;

    private void HandleSubmit()
    {
        _errorMessage = null;
        _successMessage = null;

        if (string.IsNullOrWhiteSpace(_submission.Title))
        {
            _errorMessage = "Please enter a recipe title.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_submission.Category))
        {
            _errorMessage = "Please select a category.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_submission.Ingredients))
        {
            _errorMessage = "Please enter at least one ingredient.";
            return;
        }
        if (string.IsNullOrWhiteSpace(_submission.Steps))
        {
            _errorMessage = "Please enter at least one step.";
            return;
        }

        var recipe = RecipeService.AddRecipe(_submission);
        _successMessage = $"\"{recipe.Title}\" has been submitted! View it in the {recipe.Category} category.";
        _submission = new RecipeSubmission();
    }
}

